var t=`0964-mochi`;var n=`world-0964`;var a=`JP`;var s=`east-asia`;var r=8;var o=73;var h={en:`Mochi`,ua:`Моті`};var d={en:`Mochi is a Japan dish made with sweet rice flour, cornstarch, red bean paste (anko). This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Моті, страва кухні країни Японія. Основні складники: борошно з клейкого рису, кукурудзяний крохмаль, паста анко. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`sweet-rice-flour`,390,`g`],[`water`,430,`ml`],[`white-granulated-sugar`,75,`g`]]},{en:`Steam the sweet-rice dough until sticky and translucent, then work it carefully while warm without burning your hands.`,ua:`Пропарте тісто з клейкого рису до липкої напівпрозорої маси й обережно вимішуйте теплим, не обпікаючи рук.`,t:[`steaming`],m:28,i:[]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:15,i:[[`cornstarch`,75,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:12,i:[[`red-bean-paste-anko`,220,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,20,`g`]]}];var u={slug:t,id:n,country:`JP`,region:s,servings:8,minutes:73,title:h,text:d,steps:g};export{a as country,u as default,n as id,o as minutes,s as region,r as servings,t as slug,g as steps,d as text,h as title};